package com.smartsociety.platform.analytics; import com.smartsociety.platform.complaint.ComplaintRepository;import com.smartsociety.platform.common.Enums.*;import org.springframework.stereotype.Service;import java.time.Instant;import java.util.*;
@Service public class DashboardService {final ComplaintRepository repo;public DashboardService(ComplaintRepository r){repo=r;}public Map<String,Object> dashboard(){long overdue=repo.countByDueAtBeforeAndCurrentStatusNot(Instant.now(),ComplaintStatus.RESOLVED);var out=new LinkedHashMap<String,Object>();out.put("total",repo.count());out.put("open",repo.countByCurrentStatus(ComplaintStatus.OPEN));out.put("inProgress",repo.countByCurrentStatus(ComplaintStatus.IN_PROGRESS));out.put("resolved",repo.countByCurrentStatus(ComplaintStatus.RESOLVED));out.put("overdue",overdue);out.put("byStatus",repo.countByStatus().stream().collect(java.util.stream.Collectors.toMap(x->x[0].toString(),x->x[1])));out.put("byCategory",repo.countByCategory().stream().map(x->Map.of("category",x[0],"count",x[1])).toList());return out;}}
